stageCss:
#stage .sb-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .sb-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
  transition:border-color .3s ease;
}
#stage .sb-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(240,166,74,.14); border:1.5px solid rgba(240,166,74,.42); color:var(--warn);
}
#stage .sb-mark svg{ width:25px; height:25px; }
#stage .sb-shop{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
/* The clock is the loudest thing in the header on purpose — it is the proof
   that the animation is running in real time rather than cutting between slides. */
#stage .sb-clock{
  margin-left:auto; flex-shrink:0; padding:7px 16px; border-radius:12px;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.42);
  color:var(--accent-1); font-family:var(--font-mono); font-size:26px; font-weight:700;
  font-variant-numeric:tabular-nums;
  transition:color .2s ease, border-color .2s ease, background .2s ease;
}
#stage .sb-clock.stuck{
  color:var(--danger); border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.14);
  animation:sb-stuck .28s steps(2) infinite;
}
#stage .sb-meta{ flex-shrink:0; display:flex; align-items:baseline; gap:7px; }
#stage .sb-meta b{ color:#fff; font-family:var(--font-mono); font-size:25px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .sb-meta i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .sb-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .sb-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .sb-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .sb-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .sb-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .sb-health.warn b{ color:var(--warn); }
#stage .sb-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .sb-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .sb-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .sb-body{ position:relative; flex:1; min-height:0; }
#stage .sb-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .sb-sc.on{ opacity:1; transform:none; }

/* The snap transition into the fix. One shot, fired from stage code — a hard
   horizontal whip with motion blur is what reads as a trending cut rather than
   a cross-fade. */
#stage .sb-sc.whip{ animation:sb-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .sb-glitch{
  position:absolute; inset:0; z-index:9; pointer-events:none; opacity:0; border-radius:26px;
  background:
    repeating-linear-gradient(0deg, rgba(244,74,106,.13) 0 2px, transparent 2px 6px),
    radial-gradient(circle at 50% 62%, rgba(244,74,106,.22), transparent 62%);
  transition:opacity .2s ease;
}
#stage .sb-glitch.on{ opacity:1; animation:sb-glitch .34s steps(3) infinite; }

/* ==================== SCENE 1 · ONE SERVER, NO QUEUE =================== */
#stage .sb-flood{ display:flex; flex-direction:column; gap:14px; height:100%; }

#stage .sb-buyers{
  height:92px; flex-shrink:0; display:flex; align-items:center; gap:11px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.5); border:1.5px solid var(--border);
}
#stage .sb-buyers.tight{ height:86px; }
#stage .sb-face{
  width:56px; height:56px; border-radius:16px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center; font-size:28px;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .sb-face.more{
  background:rgba(58,160,255,.14); border-color:rgba(58,160,255,.42);
  color:var(--accent-1); font-family:var(--font-mono); font-size:19px; font-weight:700;
}
#stage .sb-buyers-l{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:20px; font-weight:600; white-space:nowrap;
}

/* -------------------------------------------------------- the order rain -- */
#stage .sb-rain{
  position:relative; flex:1; min-height:0; overflow:hidden; border-radius:24px;
  border:1.5px dashed rgba(58,160,255,.22);
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.09), transparent 60%);
}
#stage .sb-ord{
  position:absolute; top:-46px; display:flex; align-items:center; gap:9px;
  padding:8px 13px; border-radius:11px; white-space:nowrap;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.4);
  font-family:var(--font-mono); font-size:18px; font-weight:600;
  animation:sb-fall 1.85s linear forwards;
}
#stage .sb-ord b{ color:#fff; font-weight:700; }
#stage .sb-ord span{ color:var(--accent-cyan); font-variant-numeric:tabular-nums; }
/* Doomed orders never reach the server: they redden, shrink and vanish in the
   gap. A dropped order has to be *seen* leaving, or "lost sales" is just a word. */
#stage .sb-ord.doomed{
  background:rgba(244,74,106,.15); border-color:rgba(244,74,106,.55);
  animation:sb-fail 1.55s ease-in forwards;
}
#stage .sb-ord.doomed b{ color:#ffd0d9; }
#stage .sb-ord.doomed span{ color:var(--danger); }
/* Freezing the fall is the backpressure beat — timestamps stop mid-tick. */
#stage .sb-rain.frozen .sb-ord{ animation-play-state:paused; }
#stage .sb-rain.frozen{ border-color:rgba(244,74,106,.4); }
#stage .sb-rain.frozen .sb-ord span{ color:var(--danger); animation:sb-stuck .3s steps(2) infinite; }

#stage .sb-countdown{
  position:absolute; inset:0; z-index:3; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:6px;
  opacity:0; transition:opacity .22s ease;
}
#stage .sb-countdown.on{ opacity:1; }
#stage .sb-countdown b{
  color:#fff; font-family:var(--font-mono); font-size:150px; font-weight:800;
  line-height:1; letter-spacing:-4px; text-shadow:0 0 60px rgba(58,160,255,.6);
}
#stage .sb-countdown span{
  color:var(--accent-1); font-size:26px; font-weight:800; letter-spacing:8px;
}
#stage .sb-countdown.go b{ color:var(--accent-cyan); font-size:112px; letter-spacing:2px; }

#stage .sb-funnel{
  height:58px; flex-shrink:0; display:flex; align-items:center; justify-content:center; gap:14px;
  color:var(--accent-1);
}
#stage .sb-funnel svg{ width:30px; height:30px; animation:sb-nudge 1.1s ease-in-out infinite; }
#stage .sb-funnel span{
  color:var(--text-dim); font-family:var(--font-mono); font-size:20px; font-weight:600; white-space:nowrap;
}

/* ------------------------------------------------------------- the server -- */
#stage .sb-srv{
  height:206px; flex-shrink:0; display:flex; flex-direction:column; gap:16px;
  padding:22px 26px; border-radius:26px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .sb-srv.hot{ border-color:rgba(240,166,74,.6); box-shadow:0 0 0 1px rgba(240,166,74,.25), 0 0 60px rgba(240,166,74,.16); }
#stage .sb-srv.bad{
  border-color:rgba(244,74,106,.7); box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 70px rgba(244,74,106,.2);
  animation:sb-alertPulse 1s ease-in-out infinite;
}
#stage .sb-srv-h{ display:flex; align-items:center; gap:16px; }
#stage .sb-srv-ic{
  width:58px; height:58px; border-radius:16px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
  transition:background .3s ease, color .3s ease;
}
#stage .sb-srv-ic svg{ width:31px; height:31px; }
#stage .sb-srv.bad .sb-srv-ic{ background:rgba(244,74,106,.16); color:var(--danger); }
#stage .sb-srv-n{ color:#fff; font-size:31px; font-weight:800; letter-spacing:-.5px; }
#stage .sb-srv-b{
  margin-left:auto; padding:8px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(63,185,80,.5); background:rgba(63,185,80,.12); color:var(--success);
  font-family:var(--font-mono); font-size:19px; font-weight:700; letter-spacing:1.4px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .sb-srv-b.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.14); color:var(--warn); }
#stage .sb-srv-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }
#stage .sb-meter{ height:20px; border-radius:10px; background:rgba(35,44,64,.9); overflow:hidden; }
#stage .sb-meter i{
  display:block; height:100%; width:14%; border-radius:10px;
  background:linear-gradient(90deg, var(--accent-1), var(--accent-cyan));
  transition:width .5s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .sb-meter i.hot{ background:linear-gradient(90deg,#F0A64A,#F4C46A); }
#stage .sb-meter i.bad{ background:linear-gradient(90deg,#F44A6A,#FF8FA3); animation:sb-alertPulse .8s ease-in-out infinite; }
#stage .sb-srv-f{
  display:flex; align-items:center; justify-content:space-between;
  color:var(--text-dim); font-family:var(--font-mono); font-size:21px; font-weight:600;
}
#stage .sb-srv-f span:last-child{ color:var(--danger); }

#stage .sb-strip{
  height:74px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .sb-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .sb-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .sb-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .sb-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .sb-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .sb-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ====================== SCENE 2 · THE QUEUE IN FRONT =================== */
#stage .sb-q{ display:flex; flex-direction:column; gap:14px; height:100%; }

#stage .sb-arr{
  flex-shrink:0; position:relative; height:62px;
  display:flex; align-items:center; gap:0;
}
#stage .sb-arr i{
  display:block; width:4px; height:30px; border-radius:2px;
  background:linear-gradient(180deg, rgba(34,211,238,.15), var(--accent-cyan));
  box-shadow:0 0 14px rgba(34,211,238,.5);
  animation:sb-pour 1s linear infinite;
}
/* The inflow ticks stay in the left half: the caption that explains them is
   pinned right, and at 992px wide the two collide if the ticks spread. */
#stage .sb-arr.in{ justify-content:flex-start; gap:58px; padding-left:76px; }
#stage .sb-arr.in i:nth-child(2){ animation-delay:.18s; }
#stage .sb-arr.in i:nth-child(3){ animation-delay:.36s; }
#stage .sb-arr.in i:nth-child(4){ animation-delay:.54s; }
#stage .sb-arr.in i:nth-child(5){ animation-delay:.72s; }
#stage .sb-arr.out{ justify-content:flex-start; padding-left:104px; }
#stage .sb-arr.out i{ height:34px; animation-duration:1.4s; }
#stage .sb-arr-t{
  position:absolute; right:24px; top:50%; transform:translateY(-50%);
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600; white-space:nowrap;
}

#stage .sb-pipe{
  flex-shrink:0; height:238px; display:flex; flex-direction:column; gap:14px;
  padding:20px 22px; border-radius:28px;
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.12), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.45);
  box-shadow:0 0 0 1px rgba(58,160,255,.16), 0 0 70px rgba(58,160,255,.14);
}
#stage .sb-pipe.live{ animation:sb-pipePulse 2.2s ease-in-out infinite; }
#stage .sb-pipe-h{ display:flex; align-items:center; gap:14px; }
#stage .sb-pipe-ic{
  width:52px; height:52px; border-radius:15px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.16); color:var(--accent-1);
}
#stage .sb-pipe-ic svg{ width:30px; height:30px; }
#stage .sb-pipe-n{ color:#fff; font-size:28px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .sb-pipe-d{ margin-left:auto; display:flex; align-items:baseline; gap:8px; white-space:nowrap; }
#stage .sb-pipe-d b{ color:var(--accent-cyan); font-family:var(--font-mono); font-size:30px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .sb-pipe-d i{ color:var(--text-dim); font-size:19px; font-weight:600; font-style:normal; }

/* The visible part of the queue. Messages are appended at the right and pulled
   from the left, so the head of the queue is where the worker arrow points. */
#stage .sb-track{
  position:relative; flex:1; min-height:0; display:flex; align-items:center; gap:10px;
  padding:0 16px; border-radius:18px; overflow:hidden;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border);
}
/* Messages keep arriving past the right edge. The fade has to reach full
   opacity well before the "+N more" pill, or a half-hidden message renders
   through it and the queue reads as broken rather than as deep. */
#stage .sb-track::after{
  content:""; position:absolute; right:0; top:0; bottom:0; width:300px; pointer-events:none;
  background:linear-gradient(90deg, rgba(14,20,32,0), rgba(14,20,32,1) 28%);
}
#stage .sb-msg{
  position:relative; z-index:1; flex-shrink:0; display:flex; align-items:center; gap:8px;
  padding:12px 14px; border-radius:12px; white-space:nowrap;
  background:rgba(34,211,238,.1); border:1.5px solid rgba(34,211,238,.42);
  font-family:var(--font-mono); font-size:18px; font-weight:600;
  animation:msd-pop .3s cubic-bezier(.22,1,.36,1);
}
#stage .sb-msg b{ color:#fff; }
#stage .sb-msg span{ color:var(--accent-cyan); font-variant-numeric:tabular-nums; }
#stage .sb-msg i{ font-style:normal; font-size:16px; }
/* A pulled message leaves the flex flow on the same frame it is taken, so the
   rest of the queue advances immediately instead of waiting for the exit
   animation to finish and leaving a hole at the head. */
#stage .sb-msg.pull{
  position:absolute; left:16px; top:calc(50% - 24px); z-index:0;
  animation:sb-pull .34s ease-in forwards;
}
#stage .sb-msg.failing{ background:rgba(240,166,74,.14); border-color:rgba(240,166,74,.6); }
#stage .sb-msg.failing span{ color:var(--warn); }
#stage .sb-more{
  position:absolute; right:16px; z-index:2; padding:9px 15px; border-radius:10px;
  background:#16233a; border:1.5px solid rgba(58,160,255,.4); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:700; white-space:nowrap;
}

#stage .sb-workers{ flex:1; min-height:0; display:flex; gap:16px; }
#stage .sb-wk{
  flex:1; display:flex; flex-direction:column; gap:10px; justify-content:center;
  padding:18px 20px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  opacity:.3; filter:saturate(.2);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, box-shadow .3s ease;
}
#stage .sb-wk.on{
  opacity:1; filter:none; border-color:rgba(63,185,80,.5);
  box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 0 46px rgba(63,185,80,.14);
}
#stage .sb-wk.on .sb-wk-ic{ background:rgba(63,185,80,.16); color:var(--success); animation:msd-spin 3.4s linear infinite; }
#stage .sb-wk-h{ display:flex; align-items:center; gap:12px; }
#stage .sb-wk-ic{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(139,149,167,.12); color:var(--text-dim);
}
#stage .sb-wk-ic svg{ width:26px; height:26px; }
#stage .sb-wk-h b{ color:#fff; font-family:var(--font-mono); font-size:23px; font-weight:700; }
#stage .sb-wk-s{
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .sb-wk.on .sb-wk-s{ color:var(--success); }
#stage .sb-wk-n{ display:flex; align-items:baseline; gap:8px; }
#stage .sb-wk-n b{ color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700; font-variant-numeric:tabular-nums; }
#stage .sb-wk-n i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }

#stage .sb-flash{
  height:88px; flex-shrink:0; display:flex; align-items:center; justify-content:center;
  border-radius:20px; background:rgba(20,27,43,.7); border:1.5px solid rgba(58,160,255,.4);
}
#stage .sb-flash b{
  color:#fff; font-size:34px; font-weight:800; letter-spacing:-.4px; white-space:nowrap;
}

/* ======================= SCENE 3 · SPLIT-SCREEN ======================== */
#stage .sb-split{ display:flex; gap:16px; height:100%; }
#stage .sb-col{
  flex:1; display:flex; flex-direction:column; align-items:center; gap:14px;
  padding:24px 20px; border-radius:28px; text-align:center;
}
#stage .sb-col.bad{
  background:radial-gradient(circle at 50% 0%, rgba(244,74,106,.16), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(244,74,106,.55);
  animation:sb-alertPulse 1.1s ease-in-out infinite;
}
#stage .sb-col.good{
  background:radial-gradient(circle at 50% 0%, rgba(63,185,80,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(63,185,80,.5);
}
#stage .sb-col-h{
  font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:2px;
}
#stage .sb-col.bad .sb-col-h{ color:var(--danger); }
#stage .sb-col.good .sb-col-h{ color:var(--success); }
#stage .sb-col-srv{
  width:100%; display:flex; flex-direction:column; align-items:center; gap:10px;
  padding:16px 12px; border-radius:20px; background:rgba(14,20,32,.6); border:1.5px solid var(--border);
}
#stage .sb-col-srv svg{ width:46px; height:46px; }
#stage .sb-col-srv b{ font-family:var(--font-mono); font-size:19px; font-weight:700; }
#stage .sb-col.bad .sb-col-srv{ color:var(--danger); }
#stage .sb-col.bad .sb-col-srv svg{ animation:msd-shake .5s ease-in-out infinite; }
#stage .sb-col.good .sb-col-srv{ color:var(--accent-cyan); }
#stage .sb-col-list{ width:100%; display:flex; flex-direction:column; gap:8px; }
#stage .sb-mini{
  padding:9px 12px; border-radius:10px; white-space:nowrap;
  background:rgba(244,74,106,.12); border:1px solid rgba(244,74,106,.35); color:#ffd0d9;
  font-family:var(--font-mono); font-size:17px; font-weight:600;
}
#stage .sb-mini.ok{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.35); color:#bff0c4; }
#stage .sb-mini.gone{ animation:sb-vanish .6s ease-in forwards; }
#stage .sb-col-n{
  margin-top:auto; color:#fff; font-family:var(--font-mono); font-size:62px; font-weight:800;
  line-height:1; font-variant-numeric:tabular-nums; letter-spacing:-2px;
}
#stage .sb-col-l{ color:var(--text-dim); font-size:20px; font-weight:600; }
#stage .sb-col-x{
  width:100%; padding:11px 10px; border-radius:14px; white-space:nowrap;
  background:rgba(244,74,106,.16); border:1.5px solid rgba(244,74,106,.5); color:var(--danger);
  font-family:var(--font-mono); font-size:20px; font-weight:700;
}
#stage .sb-col-x.ok{ background:rgba(63,185,80,.16); border-color:rgba(63,185,80,.5); color:var(--success); }

/* ========================= SCENE 4 · THE PAYOFF ======================== */
#stage .sb-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .sb-badge{
  width:132px; height:132px; border-radius:36px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(58,160,255,.28), rgba(34,211,238,.14));
  border:2px solid rgba(58,160,255,.6); color:#fff;
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 80px rgba(58,160,255,.34);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .sb-badge svg{ width:74px; height:74px; }
#stage .sb-badge-l{
  color:var(--accent-1); font-family:var(--font-mono); font-size:22px; font-weight:800; letter-spacing:5px;
}
#stage .sb-fin-h{ color:#fff; font-size:66px; font-weight:900; line-height:1.1; letter-spacing:-2px; }
#stage .sb-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .sb-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .sb-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:22px; font-weight:700;
}
#stage .sb-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:820px;
  background:linear-gradient(90deg, rgba(58,160,255,.2), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.55); color:#fff;
  font-size:27px; font-weight:700; line-height:1.35;
}
#stage .sb-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes sb-fall{
  0%{ transform:translateY(0); opacity:0; }
  10%{ opacity:1; }
  100%{ transform:translateY(520px); opacity:.9; }
}
@keyframes sb-fail{
  0%{ transform:translateY(0); opacity:0; }
  12%{ opacity:1; }
  58%{ transform:translateY(250px) rotate(0deg); opacity:1; }
  100%{ transform:translateY(320px) scale(.6) rotate(9deg); opacity:0; }
}
@keyframes sb-pull{
  0%{ transform:translateY(0) scale(1); opacity:1; }
  100%{ transform:translateY(46px) scale(.82); opacity:0; }
}
@keyframes sb-vanish{
  0%{ opacity:1; transform:none; }
  100%{ opacity:0; transform:translateX(-26px) scale(.8); }
}
@keyframes sb-pour{
  0%{ transform:translateY(-16px); opacity:0; }
  25%{ opacity:1; }
  100%{ transform:translateY(20px); opacity:0; }
}
@keyframes sb-nudge{ 0%,100%{ transform:translateY(-4px); } 50%{ transform:translateY(5px); } }
@keyframes sb-stuck{ 0%{ opacity:1; } 100%{ opacity:.45; } }
@keyframes sb-alertPulse{
  0%,100%{ box-shadow:0 0 0 1px rgba(244,74,106,.3), 0 0 40px rgba(244,74,106,.16); }
  50%{ box-shadow:0 0 0 1px rgba(244,74,106,.5), 0 0 80px rgba(244,74,106,.3); }
}
@keyframes sb-pipePulse{
  0%,100%{ box-shadow:0 0 0 1px rgba(58,160,255,.16), 0 0 50px rgba(58,160,255,.12); }
  50%{ box-shadow:0 0 0 1px rgba(58,160,255,.34), 0 0 90px rgba(58,160,255,.26); }
}
@keyframes sb-glitch{
  0%{ transform:translateX(0); }
  33%{ transform:translateX(-7px); }
  66%{ transform:translateX(6px); }
  100%{ transform:translateX(0); }
}
@keyframes sb-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

