var SB = window.__SB || (window.__SB = {});
SB.t = 0; SB.id = 4820;
// Thousands separators without Intl, so the reel renders identically in
// any browser and any locale.
SB.fmt = function(n){
  n = Math.round(n);
  var s = String(n), out = '', c = 0;
  for(var i = s.length - 1; i >= 0; i--){
    out = s.charAt(i) + out; c++;
    if(c % 3 === 0 && i > 0) out = ',' + out;
  }
  return out;
};
SB.ramp = function(sel, from, to, ms, suffix){
  var el = MSD.q(sel); if(!el) return;
  var steps = Math.max(1, Math.round(ms / 50)), i = 0;
  var id = MSD.every(50, function(){
    i++;
    var p = Math.min(1, i / steps);
    el.textContent = SB.fmt(from + (to - from) * p) + (suffix || '');
    if(p >= 1) clearInterval(id);
  });
};
function stamp(sec){ var m = Math.floor(sec / 60), x = sec % 60; return '11:0' + m + ':' + (x < 10 ? '0' : '') + x; }

