var track = MSD.q('#sb-track');
function enqueue(cls){
  // The track is a window onto a queue thousands deep. Past three
  // messages the chips would render under the "+N more" pill.
  if(track.querySelectorAll('.sb-msg:not(.pull)').length >= 3) return;
  var el = document.createElement('div');
  el.className = 'sb-msg' + (cls ? ' ' + cls : '');
  SB.id++;
  el.innerHTML = '<b>#' + SB.id + '</b><span>' + stamp(SB.t) + '</span><i>✅</i>';
  track.appendChild(el);
  return el;
}
if(track.querySelectorAll('.sb-msg').length < 3){ for(var i = 0; i < 3; i++) enqueue(); }
MSD.every(300, function(){ enqueue(); });

// The retry beat: one message fails on the worker, is not deleted, and
// reappears at the head of the queue instead of disappearing.
MSD.after(250, function(){
  var head = track.querySelector('.sb-msg');
  if(head){
    head.classList.add('failing');
    head.querySelector('i').textContent = '⚠️';
    MSD.q('#sb-wk1-s').textContent = 'worker crashed mid-order';
    MSD.shake('#sb-wk1');
  }
});
MSD.after(1000, function(){
  var head = track.querySelector('.sb-msg');
  if(head){
    head.classList.remove('failing');
    head.querySelector('i').textContent = '🔁';
    MSD.q('#sb-wk1-s').textContent = 'redelivered · attempt 2/10';
    MSD.punch('#sb-wk1', 2);
    MSD.sfx.pop();
  }
});
MSD.after(1500, function(){
  var head = track.querySelector('.sb-msg');
  if(head){
    head.querySelector('i').textContent = '✅';
    MSD.q('#sb-wk1-s').textContent = 'completed on retry ✅';
  }
  MSD.sfx.ding();
});

// Scale out. Competing consumers on one queue is the supported way to
// drain a backlog faster — no partition maths, no reshuffling.
MSD.after(1650, function(){
  MSD.q('#sb-flash-t').textContent = 'Scales workers on demand 📈';
  MSD.punch('#sb-flash', 5);
